const FormField = ({ label, id, type = "text", required, autocomplete, helperText, error, value, onChange, onBlur }) => {
    const helperId = `${id}-helper`;
    const errorId = `${id}-error`;
    const describedBy = [];
    if (helperText) describedBy.push(helperId);
    if (error) describedBy.push(errorId);

    return (
        <div className="form-field">
            <label htmlFor={id}>
                {label}
                {required && <span className="required-dot" aria-hidden="true">*</span>}
                {required && <span className="sr-only"> (required)</span>}
            </label>
            <input
                id={id}
                name={id}
                type={type}
                required={required}
                autoComplete={autocomplete}
                value={value}
                onChange={onChange}
                onBlur={onBlur}
                aria-invalid={!!error}
                aria-describedby={describedBy.length > 0 ? describedBy.join(' ') : undefined}
            />
            {helperText && (
                <div id={helperId} className="helper-text">
                    {helperText}
                </div>
            )}
            {error && (
                <div id={errorId} className="error-message">
                    Error: {error}
                </div>
            )}
        </div>
    );
};

const ContactForm = () => {
    const [formData, setFormData] = useState({
        fullName: '',
        email: '',
        phone: ''
    });

    const [errors, setErrors] = useState({});
    const [touched, setTouched] = useState({});
    const [submitted, setSubmitted] = useState(false);

    const validateField = (name, value) => {
        let error = '';
        if (name === 'fullName') {
            if (!value.trim()) error = 'Full name is required.';
        } else if (name === 'email') {
            if (!value.trim()) {
                error = 'Email address is required.';
            } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
                error = 'Enter a valid email address.';
            }
        } else if (name === 'phone') {
            if (value && !/^\+?[0-9\s-]{7,15}$/.test(value)) {
                error = 'Enter a valid phone number.';
            }
        }
        return error;
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));

        // Clear error as user types if it was already touched
        if (touched[name]) {
            const error = validateField(name, value);
            setErrors(prev => ({ ...prev, [name]: error }));
        }
    };

    const handleBlur = (e) => {
        const { name, value } = e.target;
        setTouched(prev => ({ ...prev, [name]: true }));
        const error = validateField(name, value);
        setErrors(prev => ({ ...prev, [name]: error }));
    };

    const handleSubmit = (e) => {
        e.preventDefault();

        const newErrors = {};
        Object.keys(formData).forEach(key => {
            const error = validateField(key, formData[key]);
            if (error) newErrors[key] = error;
        });

        setErrors(newErrors);
        setTouched({
            fullName: true,
            email: true,
            phone: true
        });

        if (Object.keys(newErrors).length === 0) {
            setSubmitted(true);
            // In a real app, you'd send data to server here
        } else {
            // Accessibility: Focus the first invalid field
            const firstErrorField = Object.keys(newErrors)[0];
            document.getElementById(firstErrorField)?.focus();
        }
    };

    if (submitted) {
        return (
            <div className="container" role="status">
                <h1>Thank You!</h1>
                <p>Your support request has been submitted. We'll get back to you soon.</p>
                <button 
                    onClick={() => {
                        setSubmitted(false);
                        setFormData({ fullName: '', email: '', phone: '' });
                        setErrors({});
                        setTouched({});
                    }}
                >
                    Send another message
                </button>
            </div>
        );
    }

    return (
        <div className="container">
            <header>
                <h1>Contact Support</h1>
                <p className="subtitle">Fill out the form below and we'll help you out.</p>
            </header>
            <form onSubmit={handleSubmit} noValidate>
                <FormField
                    id="fullName"
                    label="Full Name"
                    required={true}
                    autocomplete="name"
                    value={formData.fullName}
                    onChange={handleChange}
                    onBlur={handleBlur}
                    error={touched.fullName && errors.fullName}
                />
                <FormField
                    id="email"
                    label="Email Address"
                    type="email"
                    required={true}
                    autocomplete="email"
                    value={formData.email}
                    onChange={handleChange}
                    onBlur={handleBlur}
                    error={touched.email && errors.email}
                />
                <FormField
                    id="phone"
                    label="Phone Number"
                    type="tel"
                    required={false}
                    autocomplete="tel"
                    helperText="Format: +1 234 567 8900"
                    value={formData.phone}
                    onChange={handleChange}
                    onBlur={handleBlur}
                    error={touched.phone && errors.phone}
                />
                <button type="submit">Submit Support Request</button>
            </form>
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<ContactForm />);
